    pub const ATTR_MAX_DEVICE_VOLUME_DB: AttributeId = AttributeId::new(0x0005);
    pub const ATTR_MAX_USER_VOLUME: AttributeId = AttributeId::new(0x0006);
    pub const ATTR_MID: AttributeId = AttributeId::new(0x000F);
    pub const ATTR_MIN_CORRECTION: AttributeId = AttributeId::new(0x0011);
    pub const ATTR_MIN_DEVICE_VOLUME: AttributeId = AttributeId::new(0x0003);
    pub const ATTR_PHYSICALLY_MUTED: AttributeId = AttributeId::new(0x0001);
    pub const ATTR_SET_VOLUME_UNMUTE_POLICY: AttributeId = AttributeId::new(0x0008);
    pub const ATTR_SOFT_MUTED: AttributeId = AttributeId::new(0x0000);
    pub const ATTR_START_UP_MUTED: AttributeId = AttributeId::new(0x000C);
    pub const ATTR_START_UP_VOLUME: AttributeId = AttributeId::new(0x000D);
    pub const ATTR_TREBLE: AttributeId = AttributeId::new(0x0010);
    pub const ATTR_VOLUME: AttributeId = AttributeId::new(0x0002);
    pub const CLUSTER_ID: ClusterId = ClusterId::new(0x0512);
    pub const CLUSTER_REVISION: u16 = 1;
    pub const NAME: &'static str = "AudioControl";

    #[must_use]
    pub fn new(
        soft_muted: impl Into<SoftMuted>,
        volume: impl Into<u16>,
        min_device_volume: impl Into<u16>,
        max_device_volume: impl Into<u16>,
        default_step_size: impl Into<u16>,
        set_volume_unmute_policy: impl Into<UnmutePolicyEnum>,
        increase_volume_unmute_policy: impl Into<UnmutePolicyEnum>,
        increase_volume_unmute_volume: impl Into<UnmuteVolumeEnum>,
        decrease_volume_unmute_policy: impl Into<UnmutePolicyEnum>,
    ) -> Self {
        Self {
            soft_muted: soft_muted.into(),
            volume: volume.into(),
            min_device_volume: min_device_volume.into(),
            max_device_volume: max_device_volume.into(),
            default_step_size: default_step_size.into(),
            set_volume_unmute_policy: set_volume_unmute_policy.into(),
            increase_volume_unmute_policy: increase_volume_unmute_policy.into(),
            increase_volume_unmute_volume: increase_volume_unmute_volume.into(),
            decrease_volume_unmute_policy: decrease_volume_unmute_policy.into(),
            physically_muted: Optional::Omitted,
            max_device_volume_db: Optional::Omitted,
            max_user_volume: Optional::Omitted,
            start_up_muted: Optional::Omitted,
            start_up_volume: Optional::Omitted,
            bass: Optional::Omitted,
            mid: Optional::Omitted,
            treble: Optional::Omitted,
            min_correction: Optional::Omitted,
            max_correction: Optional::Omitted,
        }
    }

